package android.content;import java.util.*;import android.os.*;import android.net.Uri;public class Intent {public static final String ACTION_MAIN="android.intent.action.MAIN",CATEGORY_HOME="android.intent.category.HOME",ACTION_SCREEN_OFF="android.intent.action.SCREEN_OFF",ACTION_SHUTDOWN="android.intent.action.ACTION_SHUTDOWN";public static final int FLAG_ACTIVITY_NEW_TASK=0x10000000,FLAG_ACTIVITY_CLEAR_TOP=0x4000000,FLAG_ACTIVITY_SINGLE_TOP=0x20000000,FLAG_ACTIVITY_NO_ANIMATION=65536,FLAG_RECEIVER_FOREGROUND=0x10000000;public Map<String,Object> extras=new HashMap<>();private String action,targetPackage;private ComponentName component;public Intent(){}public Intent(String a){action=a;}public Intent(Intent i){action=i.action;targetPackage=i.targetPackage;component=i.component;extras.putAll(i.extras);}public Intent(Context c,Class<?> cls){component=new ComponentName(c.getPackageName(),cls.getName());}public Intent setAction(String a){action=a;return this;}public String getAction(){return action;}public Intent setData(Uri u){return this;}public Intent setComponent(ComponentName c){component=c;return this;}public ComponentName getComponent(){return component;}public Intent addCategory(String c){return this;}public Intent addFlags(int f){return this;}public Intent setPackage(String p){targetPackage=p;return this;}public String getPackage(){return targetPackage;}public Intent putExtra(String k,boolean v){extras.put(k,v);return this;}public Intent putExtra(String k,int v){extras.put(k,v);return this;}public Intent putExtra(String k,long v){extras.put(k,v);return this;}public Intent putExtra(String k,String v){extras.put(k,v);return this;}public Intent putExtra(String k,Parcelable v){extras.put(k,v);return this;}public Intent putExtras(Intent i){extras.putAll(i.extras);return this;}public boolean hasExtra(String k){return extras.containsKey(k);}public boolean getBooleanExtra(String k,boolean d){Object v=extras.get(k);return v==null?d:(Boolean)v;}public long getLongExtra(String k,long d){Object v=extras.get(k);return v==null?d:(Long)v;}public int getIntExtra(String k,int d){Object v=extras.get(k);return v==null?d:(Integer)v;}public String getStringExtra(String k){return (String)extras.get(k);}@SuppressWarnings("unchecked")public <T extends Parcelable>T getParcelableExtra(String k){return (T)extras.get(k);}}